// Purpose: ROW-134 (REQ-008, REQ-001) — through the check endpoint, enclitic verb forms (Postúlate,
// Envíanos, Únete, sumate, postulate, and a generated sample) are not flagged, while the same forms built
// on a misspelled stem are flagged.
// Provenance: the row's named forms, plus forms generated by names-terms-helpers.ts encliticForms from
// Spanish conjugation and accent rules over a hand-typed list of job-offer verbs — independent of the
// product's dictionary; misspelled stems made fresh per run (adjacent-letter swaps, checked against the
// dictionary oracle); no expected value comes from the product.
//
// Test argument
// ROW-134 promise: enclitic verb forms are not flagged over a generated sample, while the same forms on
//   a misspelled stem are flagged (REQ-008 general Spanish, voseo included, counts as correct; REQ-001
//   flags what the dictionary does not hold — the stem decides; A-012).
// ROW-134 wrong product: the bare dictionary, which holds "Únete" but not "postúlate", "sumate" or the
//   voseo "postulate" (the call-to-action of nearly every offer, flagged); or the overreach, accepting
//   any word that ends in -te/-nos/-se, so "potsúlate" passes.
// ROW-134 given: the named five plus tú, voseo and usted imperatives, infinitives and gerunds with te,
//   se or nos for ~19 verbs, half opening a sentence (title case), half mid-sentence; and the same
//   shapes on ~12 fresh misspelled stems (two letters swapped), mid-sentence and opening a sentence;
//   when: POST /api/check; then: exactly the misspelled-stem forms are flagged, at their offsets.
// ROW-134 controls: the misspelled-stem forms are flagged in a text without any correct enclitic —
//   the path to a flag is reached, so the correct forms' silence is acceptance.
// ROW-134 technique: a property over a generated sample (the forms come from conjugation rules, never
//   from the dictionary under test), plus the row's named examples; decoys one letter-swap apart in the
//   same text; exact comparison.
// cases: ROW-134 target=ROW-134-enclitic-forms-not-flagged-and-the-same-forms-on-a-misspelled-stem-flagged control=ROW-134-control-misspelled-stem-forms-flagged-on-their-own

import { test } from '@playwright/test';
import { asActor, freshRandom, isDictionaryWord, type Rng } from './harness';
import { Offer, encliticForms, expectExact, fillers, paginate, titleCase, type CliticSet } from './names-terms-helpers';

// Verbs job offers address the reader with (calls to action), and the clitics each takes.
const VERBS: [string, CliticSet][] = [
  ['postular', 'reflexive'], ['sumar', 'reflexive'], ['unir', 'reflexive'], ['inscribir', 'reflexive'],
  ['registrar', 'reflexive'], ['presentar', 'reflexive'], ['animar', 'reflexive'], ['apuntar', 'reflexive'],
  ['anotar', 'reflexive'], ['incorporar', 'reflexive'], ['comunicar', 'reflexive'], ['atrever', 'reflexive'],
  ['contactar', 'object'], ['escribir', 'object'], ['llamar', 'object'], ['visitar', 'object'],
  ['consultar', 'object'], ['acompañar', 'object'], ['buscar', 'object'],
];
const NAMED = ['Postúlate', 'Envíanos', 'Únete', 'sumate', 'postulate'];

/** Two adjacent letters of the verb's stem swapped, so that no form of it is a dictionary word. */
function misspelledVerb(rng: Rng): [string, CliticSet] {
  for (;;) {
    const [inf, set] = rng.pick(VERBS);
    const stem = inf.slice(0, -2);
    const i = rng.int(stem.length - 1);
    if (stem[i] === stem[i + 1]) continue;
    const bad = stem.slice(0, i) + stem[i + 1] + stem[i] + stem.slice(i + 2) + inf.slice(-2);
    let forms: string[];
    try {
      forms = encliticForms(bad, set);
    } catch {
      continue; // the swap made a diphthong the accent rule does not place
    }
    if (!isDictionaryWord(bad) && forms.every((f) => !isDictionaryWord(f) && !isDictionaryWord(titleCase(f)))) return [bad, set];
  }
}

test('ROW-134-enclitic-forms-not-flagged-and-the-same-forms-on-a-misspelled-stem-flagged', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  type Item = { form: string; ok: boolean; label: string };
  const items: Item[] = NAMED.map((f) => ({ form: f, ok: true, label: `named ${f}` }));
  for (const [inf, set] of VERBS) for (const f of encliticForms(inf, set)) items.push({ form: f, ok: true, label: `enclitic form of ${inf}` });
  for (let i = 0; i < 12; i++) {
    const [bad, set] = misspelledVerb(rng);
    for (const f of rng.shuffle(encliticForms(bad, set)).slice(0, 2)) items.push({ form: f, ok: false, label: `enclitic form of misspelled ${bad}` });
  }
  if (items.filter((x) => x.ok).length < 100) throw new Error('setup: the generated enclitic sample is too small');

  const offers = paginate(
    rng.shuffle(items),
    (o, it) => {
      const opening = /^[A-ZÁÉÍÓÚ]/.test(it.form) || rng.int(2) === 0;
      const form = opening ? titleCase(it.form) : it.form;
      o.put(opening ? rng.pick(['. ', '\n', '! ']) : ' ' + fillers(rng, 1 + rng.int(2)) + rng.pick([' ', ', ']));
      if (it.ok) o.keep(form, it.label);
      else o.flag(form, it.label);
      o.put(' ' + fillers(rng, 2));
    },
    (o) => o.put(fillers(rng, 2, { capital: true })),
  );
  for (const o of offers) await expectExact(o, `ROW-134: enclitic verb forms are not flagged while the same forms on a misspelled stem are (seed ${rng.seed})`);
});

test('ROW-134-control-misspelled-stem-forms-flagged-on-their-own', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = new Offer().put(fillers(rng, 2, { capital: true }));
  for (let i = 0; i < 4; i++) {
    const [bad, set] = misspelledVerb(rng);
    o.put(' ' + fillers(rng, 2) + ' ').flag(rng.pick(encliticForms(bad, set)), `enclitic form of misspelled ${bad}`);
  }
  o.put(' ' + fillers(rng, 2) + '.');
  await expectExact(o, `ROW-134 control: forms on misspelled stems are flagged in a text with no correct enclitic (seed ${rng.seed})`);
});
